function solve(words, maxWidth) {
    const lines = [];
    let i = 0;
    while (i < words.length) {
        let j = i, total = words[i].length;
        while (j + 1 < words.length && total + 1 + words[j + 1].length <= maxWidth) {
            j++;
            total += 1 + words[j].length;
        }
        const count = j - i + 1;
        let line;
        if (j === words.length - 1 || count === 1) {
            line = words.slice(i, j + 1).join(" ");
            line += " ".repeat(maxWidth - line.length);
        } else {
            const letters = total - (count - 1);
            const spaces = maxWidth - letters;
            const gaps = count - 1;
            const base = Math.floor(spaces / gaps);
            const extra = spaces % gaps;
            line = "";
            for (let k = i; k <= j; k++) {
                line += words[k];
                if (k < j) line += " ".repeat(base + (k - i < extra ? 1 : 0));
            }
        }
        lines.push(line);
        i = j + 1;
    }
    return lines;
}

