reference_solution:
function solve(a, b) {
    const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
    const isPlain = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
    const equal = (x, y) => {
        if (x === y) return true;
        if (x === null || y === null || typeof x !== 'object' || typeof y !== 'object') return false;
        if (Array.isArray(x) !== Array.isArray(y)) return false;
        const kx = Object.keys(x);
        if (kx.length !== Object.keys(y).length) return false;
        return kx.every((k) => has(y, k) && equal(x[k], y[k]));
    };
    const changes = [];
    const walk = (x, y, prefix) => {
        const keys = new Set([...Object.keys(x), ...Object.keys(y)]);
        for (const key of keys) {
            const path = prefix === '' ? key : prefix + '.' + key;
            if (!has(y, key)) changes.push({ path, type: 'removed', from: x[key] });
            else if (!has(x, key)) changes.push({ path, type: 'added', to: y[key] });
            else if (isPlain(x[key]) && isPlain(y[key])) walk(x[key], y[key], path);
            else if (!equal(x[key], y[key])) changes.push({ path, type: 'changed', from: x[key], to: y[key] });
        }
    };
    walk(a, b, '');
    changes.sort((p, q) => (p.path < q.path ? -1 : p.path > q.path ? 1 : 0));
    return changes;
}

