function solve(config) {
    const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
    const state = new Map();
    const resolved = {};
    const resolve = (name) => {
        if (state.get(name) === 'done') return resolved[name];
        if (state.get(name) === 'visiting') return null;
        state.set(name, 'visiting');
        let failed = false;
        const text = config[name].replace(/\$\{([^}]*)\}/g, (match, ref) => {
            if (!has(config, ref)) { failed = true; return ''; }
            const value = resolve(ref);
            if (value === null) { failed = true; return ''; }
            return value;
        });
        resolved[name] = failed ? null : text;
        state.set(name, 'done');
        return resolved[name];
    };
    for (const name of Object.keys(config)) resolve(name);
    return resolved;
}

